+/* ------------------------------------------------------------------ */
+let last = performance.now();
+function loop(now) {
+  const dt = Math.min(0.033, Math.max(0, (now - last) / 1000));
+  last = now;
+  game.time += dt;
+  if (game.state === 'title') {
+    game.titleTime += dt;
+  } else if (game.state === 'play') {
+    update(dt);
+  } else if (game.state === 'map') {
+    renderer.drawMap(game);
+  }
+  renderer.render(game);
+  requestAnimationFrame(loop);
+}
