+function boot() {
+  game.rooms = buildRooms();
+  initUI();
+  refreshTitleButtons();
+  showScreen('titleScreen');
+  game.titleTime = 0;
+  requestAnimationFrame(loop);
+
+  // small debug/verification surface (harmless in production)
+  window.SUMP = {
+    game,
+    enterRoom,
+    grantAbility,
+    startBoss,
+    defeatBoss,
+    teleport(room, x, y) {
