1260:             ctx.beginPath();
1261:             ctx.moveTo(-6 + i * 6, -8 + w);
1262:             ctx.lineTo(-10 + i * 8, 1);
1263:             ctx.stroke();
1264:           }
1265:           ctx.beginPath();
1266:           ctx.moveTo(10, -16 + w);
1267:           ctx.quadraticCurveTo(20, -22 + w, 23, -28 + w);
1268:           ctx.moveTo(10, -13 + w);
1269:           ctx.quadraticCurveTo(20, -14 + w, 24, -20 + w);
1270:           ctx.stroke();
1271:           ctx.fillStyle = '#ffcf6a';
1272:           ctx.fillRect(8, -17 + w, 2, 2);
1273:           if (e.fly) {
1274:             ctx.globalAlpha = 0.3;
1275:             ctx.fillStyle = '#c8d8b0';
1276:             ctx.beginPath();
1277:             ctx.ellipse(-4, -22 + w, 11, 4, -0.4, 0, Math.PI * 2);
1278:             ctx.ellipse(6, -22 + w, 11, 4, 0.4, 0, Math.PI * 2);
1279:             ctx.fill();
1280:           }
1281:           break;
1282:         }
1283:         case 'sludge': {
1284:           ctx.translate(px, py);
1285:           const squash = 1 + Math.sin(time * 5 + e.seed) * 0.06;
1286:           ctx.fillStyle = 'rgba(80,180,100,.18)';
1287:           ctx.beginPath();
1288:           ctx.arc(0, -10, 20, 0, Math.PI * 2);
1289:           ctx.fill();
1290:           ctx.fillStyle = '#4f9a5c';
1291:           ctx.beginPath();
1292:           ctx.ellipse(0, -12, 18, 15 * squash, 0, 0, Math.PI * 2);
1293:           ctx.fill();
1294:           ctx.fillStyle = '#74c778';
1295:           ctx.beginPath();
1296:           ctx.ellipse(-4, -16, 10, 7, 0, 0, Math.PI * 2);
1297:           ctx.fill();
1298:           ctx.fillStyle = '#10200f';
1299:           ctx.fillRect(-7, -16, 3, 4);
1300:           ctx.fillRect(4, -16, 3, 4);
1301:           ctx.fillStyle = '#e8ffd0';
1302:           ctx.fillRect(-6, -15, 1, 2);
1303:           ctx.fillRect(5, -15, 1, 2);
1304:           break;
1305:         }
1306:         case 'blast': {
1307:           ctx.translate(px, py);
1308:           ctx.fillStyle = '#2f3b32';
1309:           ctx.fillRect(-16, -24, 32, 24);
1310:           ctx.strokeStyle = '#5c6b58';
1311:           ctx.lineWidth = 2;
1312:           ctx.strokeRect(-16, -24, 32, 24);
1313:           ctx.fillStyle = '#0e1710';
1314:           ctx.beginPath();
1315:           ctx.arc(0, -14, 8, 0, Math.PI * 2);
1316:           ctx.fill();
1317:           ctx.fillStyle = e.dir > 0 ? '#7f8d6f' : '#7f8d6f';
1318:           ctx.fillRect(e.dir > 0 ? 12 : -20, -18, 8, 8);
1319:           ctx.strokeStyle = '#92a287';
1320:           ctx.beginPath();
1321:           ctx.arc(0, -14, 11, 0, Math.PI * 2);
1322:           ctx.stroke();
1323:           ctx.fillStyle = '#ff8f5c';
1324:           ctx.fillRect(-9, -22, 3, 3);
1325:           break;
1326:         }
1327:       }
1328:       ctx.restore();
1329:       ctx.globalAlpha = 1;
1330: 
1331:       // hp pips
1332:       if (e.hp < e.maxHp && e.kind !== 'rat') {
1333:         const w = 24;
1334:         ctx.fillStyle = 'rgba(0,0,0,.5)';
1335:         ctx.fillRect(px - w / 2, py - e.h - 10, w, 3);
1336:         ctx.fillStyle = '#d6ff8a';
1337:         ctx.fillRect(px - w / 2, py - e.h - 10, w * (e.hp / e.maxHp), 3);
1338:       }
1339:     }
1340:   }
