1342:   drawBoss(game, cam, time) {
1343:     const { ctx } = this;
1344:     const b = game.boss;
1345:     if (!b || b.dead) return;
1346:     const px = b.x + b.w / 2 - cam.x;
1347:     const py = b.y + b.h - cam.y;
1348:     ctx.save();
1349:     if (b.hurtFlash > 0) ctx.globalAlpha = 0.8;
1350:     if (b.kind === 'warden') {
1351:       ctx.translate(px, py);
1352:       const squash = b.state === 'telegraph' ? 0.82 : 1;
1353:       ctx.fillStyle = 'rgba(60,160,90,.14)';
1354:       ctx.beginPath();
1355:       ctx.arc(0, -40, 70, 0, Math.PI * 2);
1356:       ctx.fill();
1357:       ctx.fillStyle = b.enraged ? '#6a8b3c' : '#4f8f58';
1358:       ctx.beginPath();
1359:       ctx.ellipse(0, -38, 58 * (2 - squash), 44 * squash, 0, 0, Math.PI * 2);
1360:       ctx.fill();
1361:       ctx.fillStyle = '#6fb26a';
1362:       ctx.beginPath();
1363:       ctx.ellipse(-8, -52, 32, 24, 0, 0, Math.PI * 2);
1364:       ctx.fill();
1365:       // eyes
1366:       const glow = b.state === 'telegraph' ? '#ff8f5c' : '#d6ff8a';
1367:       ctx.fillStyle = '#12220f';
1368:       ctx.beginPath();
1369:       ctx.arc(-16, -54, 9, 0, Math.PI * 2);
1370:       ctx.arc(16, -54, 9, 0, Math.PI * 2);
1371:       ctx.fill();
1372:       ctx.fillStyle = glow;
1373:       ctx.beginPath();
1374:       ctx.arc(-14, -54, 3.5, 0, Math.PI * 2);
1375:       ctx.arc(18, -54, 3.5, 0, Math.PI * 2);
1376:       ctx.fill();
1377:       // pipe crown
1378:       ctx.strokeStyle = '#9aa58c';
1379:       ctx.lineWidth = 5;
1380:       for (let i = -2; i <= 2; i++) {
1381:         ctx.beginPath();
1382:         ctx.moveTo(i * 18, -78);
1383:         ctx.lineTo(i * 20, -96 + Math.abs(i) * 6);
1384:         ctx.stroke();
1385:       }
1386:       ctx.fillStyle = '#3c4a37';
1387:       ctx.fillRect(-44, -86, 88, 6);
1388:       // drips
1389:       ctx.fillStyle = 'rgba(150,255,150,.5)';
1390:       for (let i = 0; i < 4; i++) {
1391:         ctx.fillRect(-40 + i * 26, -20 + Math.sin(time * 3 + i) * 5, 3, 10);
1392:       }
1393:     } else {
1394:       // croc
1395:       const dir = b.facing;
1396:       ctx.translate(px, py);
1397:       ctx.scale(dir, 1);
1398:       const angry = b.phase >= 2;
1399:       ctx.fillStyle = 'rgba(185,242,60,.1)';
1400:       ctx.beginPath();
1401:       ctx.ellipse(0, -40, 100, 52, 0, 0, Math.PI * 2);
1402:       ctx.fill();
1403:       // tail
1404:       ctx.strokeStyle = '#3d4a2e';
1405:       ctx.lineWidth = 26;
1406:       ctx.lineCap = 'round';
1407:       ctx.beginPath();
1408:       ctx.moveTo(-45, -30);
1409:       ctx.quadraticCurveTo(-100, -20 + Math.sin(time * 2) * 8, -118, -4);
1410:       ctx.stroke();
1411:       ctx.fillStyle = '#4d5c38';
1412:       ctx.beginPath();
1413:       ctx.ellipse(0, -48, 70, 38, 0, 0, Math.PI * 2);
1414:       ctx.fill();
1415:       // back ridges
1416:       ctx.fillStyle = '#2f3c23';
1417:       for (let i = 0; i < 6; i++) {
1418:         const rx = -50 + i * 18;
1419:         ctx.beginPath();
1420:         ctx.moveTo(rx, -80);
1421:         ctx.lineTo(rx + 7, -92);
1422:         ctx.lineTo(rx + 14, -80);
1423:         ctx.closePath();
1424:         ctx.fill();
1425:       }
1426:       // snout
1427:       ctx.fillStyle = '#55643d';
1428:       roundRect(ctx, 22, -58, 82, 30, 8);
1429:       ctx.fill();
1430:       ctx.fillStyle = '#3d4a2e';
1431:       roundRect(ctx, 22, -40, 82, 14, 6);
1432:       ctx.fill();
1433:       // teeth
1434:       ctx.fillStyle = '#ded8b8';
1435:       for (let i = 0; i < 8; i++) {
1436:         ctx.fillRect(32 + i * 9, -42, 4, 7);
1437:       }
1438:       // jaw line
1439:       ctx.strokeStyle = '#232d19';
1440:       ctx.lineWidth = 2;
1441:       ctx.beginPath();
1442:       ctx.moveTo(24, -38);
1443:       ctx.lineTo(103, -38);
1444:       ctx.stroke();
1445:       // eye
1446:       ctx.fillStyle = '#1a2114';
1447:       ctx.beginPath();
1448:       ctx.arc(60, -64, 10, 0, Math.PI * 2);
1449:       ctx.fill();
1450:       ctx.fillStyle = angry ? '#ff5c3c' : '#d6ff6a';
1451:       ctx.beginPath();
1452:       ctx.arc(62, -64, 4, 0, Math.PI * 2);
1453:       ctx.fill();
1454:       ctx.fillStyle = 'rgba(255,255,220,.8)';
1455:       ctx.fillRect(63, -66, 2, 2);
1456:       // nostrils
1457:       ctx.fillStyle = '#232d19';
1458:       ctx.fillRect(94, -54, 4, 4);
1459:       // legs
1460:       ctx.fillStyle = '#3d4a2e';
1461:       ctx.fillRect(-18, -20, 20, 20);
1462:       ctx.fillRect(28, -18, 18, 18);
1463:       // belly glow
1464:       ctx.globalAlpha = 0.25;
1465:       ctx.fillStyle = '#b9f23c';
1466:       ctx.fillRect(-30, -26, 60, 8);
1467:       ctx.globalAlpha = 1;
1468:     }
1469:     ctx.restore();
1470:     ctx.globalAlpha = 1;
1471:   }
