1500:   drawLighting(game) {
1501:     const { lctx, lightCanvas, ctx } = this;
1502:     const def = game.room;
1503:     const cam = game.cam;
1504:     lctx.setTransform(0.5, 0, 0, 0.5, 0, 0);
1505:     lctx.clearRect(0, 0, VIEW_W, VIEW_H);
1506:     lctx.globalCompositeOperation = 'source-over';
1507:     const dark = clamp(0.9 - (def.light ?? 0.3), 0.34, 0.72);
1508:     lctx.fillStyle = `rgba(2,6,7,${dark})`;
1509:     lctx.fillRect(0, 0, VIEW_W, VIEW_H);
1510:     lctx.globalCompositeOperation = 'destination-out';
1511: 
1512:     const punch = (x, y, r, strength = 1) => {
1513:       if (x < -r || x > VIEW_W + r || y < -r || y > VIEW_H + r) return;
1514:       lctx.globalAlpha = strength;
1515:       lctx.drawImage(this.lightSprite, x - r, y - r, r * 2, r * 2);
1516:       lctx.globalAlpha = 1;
1517:     };
1518: 
1519:     const p = game.player;
1520:     if (p) punch(p.x + p.w / 2 - cam.x, p.y + p.h / 2 - cam.y, 230 + Math.sin(game.time * 9) * 5, 0.98);
1521:     for (const prop of def.props) {
1522:       if (prop.type === 'lamp') punch(prop.x * T - cam.x, prop.y * T + 38 - cam.y, prop.radius || 190, 0.9);
1523:       if (prop.type === 'bench') punch(prop.x * T - cam.x, prop.y * T - 56 - cam.y, 150, 0.75);
1524:       if (prop.type === 'waterfall') punch(prop.x * T - cam.x, prop.y * T - cam.y + 80, 150, 0.25);
1525:       if (prop.type === 'lift') punch(prop.x * T + 2 * T - cam.x, prop.y * T - cam.y + 120, 90, game.updraftActive ? 0.75 : 0.15);
1526:     }
1527:     for (const h of def.hazards) {
1528:       if (h.type === 'sludge') {
1529:         punch((h.x + h.w / 2) * T - cam.x, (h.y + h.h / 2) * T - cam.y, Math.max(90, h.w * 14), 0.28);
1530:       }
1531:     }
1532:     for (const it of game.items) {
1533:       if (it.taken) continue;
1534:       if (it.bossDrop && !game.bosses[it.bossDrop]) continue;
1535:       punch(it.x * T - cam.x, it.y * T - cam.y, it.type === 'relic' ? 120 : 70, 0.65);
1536:     }
1537:     if (game.boss && !game.boss.dead) {
1538:       punch(game.boss.x + game.boss.w / 2 - cam.x, game.boss.y + game.boss.h / 2 - cam.y, 160, 0.4);
1539:     }
1540:     lctx.setTransform(1, 0, 0, 1, 0, 0);
1541:     lctx.globalCompositeOperation = 'source-over';
1542:     ctx.drawImage(lightCanvas, 0, 0, VIEW_W, VIEW_H);
1543: 
1544:     // additive glows
1545:     ctx.save();
1546:     ctx.globalCompositeOperation = 'screen';
1547:     const glow = (x, y, r, color, alpha) => {
1548:       if (x < -r || x > VIEW_W + r || y < -r || y > VIEW_H + r) return;
1549:       ctx.globalAlpha = alpha;
1550:       ctx.drawImage(this.glowSprite(color), x - r, y - r, r * 2, r * 2);
1551:       ctx.globalAlpha = 1;
1552:     };
1553:     if (p) glow(p.x + p.w / 2 - cam.x, p.y + p.h / 2 - cam.y, 210, THEMES[def.theme]?.lamp || '#ffc06a', 0.12);
1554:     for (const prop of def.props) {
1555:       if (prop.type === 'lamp') glow(prop.x * T - cam.x, prop.y * T + 38 - cam.y, prop.radius || 190, prop.color || '#ffc06a', 0.19);
1556:       if (prop.type === 'bench') glow(prop.x * T - cam.x, prop.y * T - 56 - cam.y, 130, '#a6ff9a', 0.15);
1557:     }
1558:     for (const it of game.items) {
1559:       if (it.taken) continue;
1560:       if (it.bossDrop && !game.bosses[it.bossDrop]) continue;
1561:       const col = it.type === 'token' ? '#ffd86a' : it.type === 'cell' ? '#ff6b5a' : '#b9f23c';
1562:       glow(it.x * T - cam.x, it.y * T - cam.y, 60, col, 0.2);
1563:     }
1564:     ctx.restore();
1565:   }
