1596:     ctx.save();
1597:     ctx.translate(tx, 32);
1598:     ctx.fillStyle = '#d8a93f';
1599:     tokenPath(ctx, 0, 0, 8);
1600:     ctx.fill();
1601:     ctx.fillStyle = '#0c1209';
