1612:       ctx.fillStyle = 'rgba(210,230,200,.42)';
1613:       ctx.font = '9px "Courier New", monospace';
1614:       ctx.textAlign = 'right';
1615:       ctx.fillText('[M] CHART', VIEW_W - 24, 56);
