        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(px, py, r, 0, Math.PI * 2);
        ctx.stroke();
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(time * 0.7);
        ctx.fillStyle = 'rgba(150,180,165,.18)';
        for (let i = 0; i < 4; i++) {
          ctx.rotate(Math.PI / 2);
          ctx.beginPath();
          ctx.ellipse(0, -r * 0.45, r * 0.2, r * 0.42, 0, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
        break;
      }
      case 'valve': {
        ctx.strokeStyle = 'rgba(210,170,120,.55)';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.arc(px, py, p.radius || 28, 0, Math.PI * 2);
      ctx.fillRect(x, y, w, h);
      ctx.strokeStyle = 'rgba(185,242,60,.55)';
      ctx.lineWidth = 2;
      for (let i = 6; i < w; i += 12) {
        ctx.beginPath();
        ctx.moveTo(x + i, y);
        ctx.lineTo(x + i, y + h);
        ctx.stroke();
      }
      ctx.globalAlpha = 0.5;
      ctx.fillStyle = '#b9f23c';
      for (let i = 0; i < 4; i++) {
        const yy = y + ((time * 70 + i * 19) % h);
        ctx.fillRect(x + 4, yy, w - 8, 2);
      }
      ctx.restore();
    }
  }

