      if (it.bossDrop && !game.bosses[it.bossDrop]) continue;
      const px = it.x * T - cam.x;
      const py = it.y * T - cam.y;
      if (px < -80 || px > VIEW_W + 80) continue;
      const bob = Math.sin(time * 2.4 + it.x) * 3;
      ctx.save();
      if (it.type === 'token') {
        ctx.translate(px, py + bob);
