        ctx.fill();
        ctx.globalAlpha = 1;
        ctx.fillStyle = '#ff8873';
        heartPath(ctx, -8, -7, 16);
        ctx.fill();
        ctx.strokeStyle = '#ffd3c6';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      } else if (it.type === 'relic') {
        ctx.translate(px, py + bob);
