        ctx.closePath();
        ctx.stroke();
        ctx.restore();
        ctx.fillStyle = '#f2ffe0';
        ctx.font = '700 11px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const glyph = RELICS[it.ability]?.glyph || '◆';
        ctx.fillText(glyph, 0, 0);
